-- =====================================================================
-- 013_raw_synthetic.sql
-- SYNTHETIC transactional data. Generated by afripulse.synthetic,
-- calibrated to real statistics, describing NO real people or businesses.
-- Run as: admin, connected to the 'afripulse' database. Idempotent.
--
-- Every table carries is_synthetic (always true, enforced by CHECK) and
-- generator_run_id (the audit run that produced it).
-- =====================================================================

SET ROLE afripulse_app;

CREATE TABLE IF NOT EXISTS raw_synthetic.calibration (
    country_iso3      text     NOT NULL,
    metric            text     NOT NULL,
    value             numeric  NOT NULL,
    source            text     NOT NULL,   -- table it came from, or 'default'
    source_year       integer,
    generator_run_id  uuid     NOT NULL,
    PRIMARY KEY (country_iso3, metric)
);
COMMENT ON TABLE raw_synthetic.calibration IS
    'Real statistics used to calibrate the synthetic data (or the default used when missing)';

CREATE TABLE IF NOT EXISTS raw_synthetic.customers (
    customer_id        text     PRIMARY KEY,
    country_iso3       text     NOT NULL,
    city               text     NOT NULL,
    gender             text     NOT NULL CHECK (gender IN ('female', 'male')),
    age_band           text     NOT NULL,
    signup_date        date     NOT NULL,
    has_mobile_money   boolean  NOT NULL,
    has_bank_account   boolean  NOT NULL,
    is_loyalty_member  boolean  NOT NULL,
    generator_run_id   uuid     NOT NULL,
    is_synthetic       boolean  NOT NULL DEFAULT true CHECK (is_synthetic)
);

CREATE TABLE IF NOT EXISTS raw_synthetic.merchants (
    merchant_id           text     PRIMARY KEY,
    merchant_name         text     NOT NULL,
    country_iso3          text     NOT NULL,
    city                  text     NOT NULL,
    category              text     NOT NULL,
    accepts_card          boolean  NOT NULL,
    accepts_mobile_money  boolean  NOT NULL,
    onboard_date          date     NOT NULL,
    generator_run_id      uuid     NOT NULL,
    is_synthetic          boolean  NOT NULL DEFAULT true CHECK (is_synthetic)
);

CREATE TABLE IF NOT EXISTS raw_synthetic.retail_transactions (
    txn_id            text           PRIMARY KEY,
    customer_id       text           NOT NULL REFERENCES raw_synthetic.customers,
    merchant_id       text           NOT NULL REFERENCES raw_synthetic.merchants,
    txn_ts            timestamp      NOT NULL,
    payment_method    text           NOT NULL
        CHECK (payment_method IN ('cash', 'card', 'mobile_money', 'bank_transfer')),
    amount_usd        numeric(12, 2) NOT NULL CHECK (amount_usd > 0),
    item_count        integer        NOT NULL CHECK (item_count > 0),
    generator_run_id  uuid           NOT NULL,
    is_synthetic      boolean        NOT NULL DEFAULT true CHECK (is_synthetic)
);

CREATE TABLE IF NOT EXISTS raw_synthetic.mobile_money_transactions (
    mm_txn_id                 text           PRIMARY KEY,
    customer_id               text           NOT NULL REFERENCES raw_synthetic.customers,
    txn_type                  text           NOT NULL,
    status                    text           NOT NULL CHECK (status IN ('completed', 'failed')),
    amount_usd                numeric(12, 2) NOT NULL CHECK (amount_usd > 0),
    fee_usd                   numeric(12, 2) NOT NULL CHECK (fee_usd >= 0),
    txn_ts                    timestamp      NOT NULL,
    counterparty_customer_id  text           REFERENCES raw_synthetic.customers,
    merchant_id               text           REFERENCES raw_synthetic.merchants,
    retail_txn_id             text           REFERENCES raw_synthetic.retail_transactions,
    generator_run_id          uuid           NOT NULL,
    is_synthetic              boolean        NOT NULL DEFAULT true CHECK (is_synthetic)
);

CREATE TABLE IF NOT EXISTS raw_synthetic.loyalty_events (
    event_id          text       PRIMARY KEY,
    customer_id       text       NOT NULL REFERENCES raw_synthetic.customers,
    event_type        text       NOT NULL CHECK (event_type IN ('earn', 'redeem')),
    points            integer    NOT NULL CHECK (points > 0),
    balance_after     integer    NOT NULL CHECK (balance_after >= 0),
    event_ts          timestamp  NOT NULL,
    retail_txn_id     text       REFERENCES raw_synthetic.retail_transactions,
    generator_run_id  uuid       NOT NULL,
    is_synthetic      boolean    NOT NULL DEFAULT true CHECK (is_synthetic)
);

COMMENT ON SCHEMA raw_synthetic IS
    'SYNTHETIC generated data. Never present as real-world observations';

RESET ROLE;
